"""Rebuild the standalone four-view dashboard from preserved source extracts.
Run: python build_dashboard.py (Python standard library only)."""
from pathlib import Path
from decimal import Decimal
import csv, io, json, re, html
ROOT=Path(__file__).resolve().parent
D=Decimal
text=(ROOT/'evidence/244a5_chart_component_inputs.txt').read_text(encoding='utf-8-sig')
def section(name):
    return list(csv.DictReader(io.StringIO(text.split(name,1)[1].split('\n=== ',1)[0].strip())))
rows=section('=== INCLUDED SOURCE-FAMILY RECORDS ===')
extra=section('=== EXPANDED ASSISTANCE ADJUSTMENTS ===')
ref=section('=== FINAL REFERENCE CONTROLS ===')
raw=(ROOT/'evidence/244a4_original_component_assembly.txt').read_text(encoding='utf-8-sig')
# Extract the actual ETL-238A annual output lines, not estimates.
lines=raw.split('=== ETL-238A ANNUAL OUTPUT ===',1)[1].strip().splitlines()
base=list(csv.DictReader(io.StringIO('\n'.join(lines))))
assert len(base)==7
names=[('SSA_OASDI','Social Security OASDI'),('MEDICARE_FFS_AB','Medicare A/B'),('MEDICARE_PART_C','Medicare C'),('MEDICARE_PART_D','Medicare D (qualified)'),('MEDICAID','Medicaid'),('CHIP','CHIP'),('VA_GDX','Veterans (VA)'),('FEDERAL_CIVILIAN_WAGES','Civilian wages'),('FEDERAL_MILITARY_WAGES','Military wages'),('USASPENDING_ASSISTANCE_ADDITIVE','Assistance obligations'),('ADDITIONAL_QUALIFIED_ASSISTANCE','Additional qualified assistance')]
colors=['#3d5b91','#377da6','#58a6b8','#8fcdd1','#477e62','#8dbb79','#946ba7','#c9914a','#e5b86b','#c36d60','#e5a08c']
all_data=[]
for y in range(2018,2025):
    yr=str(y); m={r['family_id']:D(r['included_amount_usd']) for r in rows if r['fiscal_year']==yr}
    a=next(r for r in extra if r['fiscal_year']==yr); r=next(r for r in ref if r['fiscal_year']==yr); b=next(r for r in base if r['fiscal_year']==yr)
    m['MEDICARE_PART_D']=D(r['partd_qualified_addition_usd'])
    m['ADDITIONAL_QUALIFIED_ASSISTANCE']=D(a['additional_qualified_assistance_usd'])
    parts=[m[k] for k,_ in names]
    inflow=sum(parts); taxes=D(r['irs_net_collections_candidate_usd']); bal=inflow-taxes
    assert inflow==D(r['partd_inclusive_inflows_usd']) and bal==D(r['partd_inclusive_net_irs_balance_usd'])
    covid=D(b['assistance_covid_tagged_usd']); iija=D(b['assistance_iija_tagged_usd']); both=D(b['assistance_both_tagged_usd'])
    assert covid>=0 and iija>=0 and both<=min(covid,iija)
    assert D(b['assistance_additive_usd'])==m['USASPENDING_ASSISTANCE_ADDITIVE']
    all_data.append(dict(year=y,parts=[float(x/10**9) for x in parts],inflows=float(inflow/10**9),taxes=float(taxes/10**9),balance=float(bal/10**9),covid=float(covid/10**9),iija=float(iija/10**9),both=float(both/10**9)))
# Procurement figures are context-only and never included in reference inflows.
with (ROOT/'data/243e1_first_draft_annual_balance.csv').open(newline='',encoding='utf-8-sig') as f: pr=list(csv.DictReader(f))
for d in all_data:
    r=next(x for x in pr if int(x['fiscal_year'])==d['year'])
    d['dod']=float(D(r['dod_procurement_obligations_usd'])/10**9)
    d['doe']=float(D(r['doe_procurement_obligations_usd'])/10**9)
    d['otherproc']=float(D(r['other_non_va_procurement_obligations_usd'])/10**9)
    assert D(r['partd_inclusive_inflows_usd'])==D(str(round(d['inflows']*10**9,2)))
with (ROOT/'data/244b_chart_data.csv').open('w',newline='',encoding='utf-8') as f:
    w=csv.writer(f);w.writerow(['fiscal_year']+[k for k,_ in names]+['reference_inflows_billion_usd','net_irs_billion_usd','reference_balance_billion_usd','covid_tagged_assistance_billion_usd','iija_tagged_assistance_billion_usd','covid_iija_overlap_billion_usd','dod_procurement_obligations_billion_usd','doe_procurement_obligations_billion_usd','other_non_va_procurement_obligations_billion_usd'])
    for d in all_data:w.writerow([d['year']]+d['parts']+[d[k] for k in ['inflows','taxes','balance','covid','iija','both','dod','doe','otherproc']])
JS=json.dumps(all_data,separators=(',',':'))
META=json.dumps([{'key':k,'label':n,'color':c} for (k,n),c in zip(names,colors)],separators=(',',':'))
page=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Washington Federal Fiscal Balance | Four Interactive Views</title><style>
:root{font-family:system-ui,-apple-system,Segoe UI,Arial,sans-serif;color:#173244;background:#f3f7f9}*{box-sizing:border-box}body{margin:0}main{max-width:1160px;margin:auto;padding:25px 18px 50px}h1{margin:0;font-size:clamp(1.55rem,3vw,2.3rem)}h2{font-size:1.23rem;margin:0 0 10px}.sub,.muted{color:#536b7a}.sub{margin:7px 0 16px}.warning{display:inline-block;background:#fff1d9;border:1px solid #dfc89b;border-radius:25px;padding:6px 12px;font-size:.8rem;font-weight:700;color:#705322}.tabs{display:flex;gap:7px;flex-wrap:wrap;margin:18px 0}.tabs button{background:#fff;border:1px solid #c9d8df;border-radius:9px;padding:10px 13px;color:#24465a;font:inherit;font-weight:650;cursor:pointer}.tabs button[aria-selected=true]{background:#17445c;color:#fff}.card{background:#fff;border:1px solid #dce6eb;border-radius:14px;padding:19px;margin:13px 0;box-shadow:0 3px 12px #17324408}.stats{display:flex;gap:12px;flex-wrap:wrap}.stat{flex:1;min-width:170px;background:#f1f5f7;padding:12px;border-radius:10px}.stat small{display:block;color:#58717d}.stat strong{display:block;font-size:1.45rem}.negative{color:#ae514b}.positive{color:#28805e}.layout{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(250px,1fr);gap:14px}.plot{width:100%;height:auto}.axis{fill:#58707e;font-size:12px}.legend{display:flex;gap:8px 16px;flex-wrap:wrap}.legend span{font-size:.8rem}.dot{display:inline-block;width:11px;height:11px;border-radius:2px;margin-right:5px}.selectable{cursor:pointer}.selectable:hover .border,.selectable.active .border{stroke:#193647;stroke-width:2.5}.selectable:focus{outline:2px solid #286b91}.details{border-collapse:collapse;width:100%;font-size:.84rem}.details td{padding:7px 2px;border-bottom:1px solid #edf1f4}.details td:last-child{text-align:right;white-space:nowrap;font-variant-numeric:tabular-nums}.details tr:last-child{font-weight:700;border-top:2px solid #ccd9e0}.foot{font-size:.87rem;line-height:1.55;color:#546b77}.view[hidden]{display:none}.bars{display:flex;align-items:flex-end;gap:12px;height:320px;padding:30px 6px 24px;border-bottom:1px solid #9db1bb}.barwrap{flex:1;min-width:0;height:100%;display:flex;flex-direction:column;justify-content:flex-end;align-items:center;cursor:pointer;border-radius:5px}.barwrap.active{background:#e7f1f5}.bar{width:65%;max-width:68px;min-height:1px;border-radius:3px 3px 0 0}.barwrap small{font-size:.78rem;margin-top:6px}.barwrap .value{font-size:.76rem;font-weight:700;white-space:nowrap}.contextgrid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.callout{padding:12px;border-left:3px solid #ce8b5e;background:#faf6ee;border-radius:4px}a{color:#165b7e}@media(max-width:750px){.layout,.contextgrid{grid-template-columns:1fr}.card{padding:13px}.bars{gap:3px}.barwrap .value{font-size:.64rem}}</style></head><body><main>
<h1>Washington's Federal Fiscal Balance</h1><p class="sub">FY2018–2024 · Four interactive views · Click any year to inspect the figures</p><span class="warning">QUALIFIED PROVISIONAL · NOT CERTIFIED CASH FLOW</span>
<nav class="tabs" aria-label="Data views"><button data-view="balance" aria-selected="true">1 · Fiscal balance</button><button data-view="composition" aria-selected="false">2 · Inflow composition</button><button data-view="covid" aria-selected="false">3 · COVID assistance</button><button data-view="agency" aria-selected="false">4 · DoD / DOE / Hanford</button></nav>
<div class="stats"><div class="stat"><small id="yearlabel">FY2024 inflows</small><strong id="inflows"></strong></div><div class="stat"><small>Net IRS collections</small><strong id="taxes"></strong></div><div class="stat"><small>Reference balance</small><strong id="balance" class="negative"></strong></div></div>
<section class="view" id="view-balance"><div class="card"><h2>Annual federal inflows and net IRS collections</h2><p class="foot">Blue = identified inflows; gray = net IRS collections. Click a year to update the selected-year details.</p><svg id="balanceplot" class="plot" viewBox="0 0 900 420" role="img" aria-label="Inflow and net IRS collections by year"></svg><p class="foot">Seven-year cumulative Provisional Reference: <strong>−$198.14 billion</strong>. Negative means net federal dollars withdrawn from Washington.</p></div></section>
<section class="view" id="view-composition" hidden><div class="layout"><div class="card"><h2>What makes up the identified inflows?</h2><p class="foot">Eleven components reconcile to each annual reference inflow control.</p><svg id="stackplot" class="plot" viewBox="0 0 760 430" role="img" aria-label="Stacked federal inflow composition"></svg><div id="legend" class="legend"></div></div><div class="card"><h2 id="detailheading">FY2024 component detail</h2><table class="details"><tbody id="detail"></tbody></table></div></div></section>
<section class="view" id="view-covid" hidden><div class="card"><h2>COVID-tagged assistance: a documented subset</h2><p class="foot">Orange represents the COVID-tagged portion of the ETL-236I program-level assistance subset. Gray represents the remaining established additive assistance. This is not a total estimate of pandemic spending and excludes unexamined award-level tagging.</p><div id="covidbars" class="bars"></div><div class="contextgrid"><div><h2 id="covidtitle">FY2024 tagged assistance</h2><p id="coviddetail"></p></div><div class="callout"><strong>Do not double count.</strong><p class="foot">COVID and IIJA tags may overlap. These tags are annotations within assistance already included in the reference, not new federal inflows. Qualified additional assistance is not assigned a COVID tag here.</p></div></div></div></section>
<section class="view" id="view-agency" hidden><div class="card"><h2>DoD and DOE procurement obligations</h2><p class="foot">Annual obligations, shown separately from the Provisional Reference. These figures are not cash outlays and are not added to the inflow bars. DoD and DOE are agency-level procurement categories, not complete agency expenditure totals.</p><div id="agencybars" class="bars"></div><h2 id="agencytitle">FY2024 agency context</h2><p id="agencydetail"></p><div class="callout"><strong>Hanford: amount not yet independently isolated.</strong><p class="foot">Hanford may be represented within DOE and other agency activity, but a verified site-specific expenditure or obligation series is not present in the supplied source extracts. No Hanford dollar amount is inferred from DOE totals.</p></div></div></section>
<div class="card"><h2>Evidence and interpretation</h2><p class="foot">Sources: ETL-238A source-family bridge and COVID/IIJA tags; ETL-238B8 assistance expansion; ETL-242A5 Medicare Part D; ETL-243E1 Provisional Reference and procurement bridge; ETL-244A5 extracted components. Values are shown in billions and rounded in the display; the source-dollar component totals reconcile exactly to cents. Mixed source timing, annualized SSA snapshots, partial FY2024 Medicare Part C, qualified Part D, assistance obligations, and provisional IRS refunds remain limitations. No canonical ledger authorization is implied.</p><p class="foot">Built as a self-contained HTML presentation with embedded data. For the reproducible source extracts, generator and checks, see the accompanying version-controlled presentation package.</p></div>
</main><script>const DATA=__DATA__;const META=__META__;let selected=2024;const $=x=>document.getElementById(x),NS='http://www.w3.org/2000/svg',fmt=n=>(n<0?'−':'')+'$'+Math.abs(n).toFixed(2)+'B';function el(tag,attrs,parent){let e=document.createElementNS(NS,tag);Object.entries(attrs).forEach(([k,v])=>e.setAttribute(k,v));parent.append(e);return e}function label(parent,x,y,s,attrs={}){let t=el('text',{x,y,class:'axis',...attrs},parent);t.textContent=s;return t}function pick(y){selected=y;let d=DATA.find(r=>r.year===y);$('yearlabel').textContent='FY'+y+' identified inflows';$('inflows').textContent=fmt(d.inflows);$('taxes').textContent=fmt(d.taxes);$('balance').textContent=fmt(d.balance);$('balance').className=d.balance<0?'negative':'positive';renderBalance();renderStack();renderDetails(d);renderCovid();renderAgency()}function renderBalance(){let s=$('balanceplot');s.replaceChildren();const bottom=372,scale=2.0;[0,40,80,120,160].forEach(v=>{let yy=bottom-v*scale;el('line',{x1:48,y1:yy,x2:888,y2:yy,stroke:'#e2eaee'},s);label(s,42,yy+4,'$'+v+'B',{'text-anchor':'end'})});DATA.forEach((d,i)=>{let x=67+i*116,g=el('g',{class:'selectable '+(selected===d.year?'active':''),tabindex:0,role:'button','aria-label':'Select '+d.year},s);for(let [j,v,c] of [[0,d.inflows,'#377ca0'],[1,d.taxes,'#a4b4bd']]){let h=v*scale;el('rect',{x:x+j*39,y:bottom-h,width:33,height:h,fill:c},g)}el('rect',{class:'border',x:x-4,y:bottom-Math.max(d.inflows,d.taxes)*scale-3,width:82,height:Math.max(d.inflows,d.taxes)*scale+7,fill:'none',stroke:'transparent'},g);label(g,x+36,398,d.year,{'text-anchor':'middle'});g.onclick=()=>pick(d.year);g.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();pick(d.year)}}});label(s,720,25,'Blue: inflows   Gray: net IRS')}function renderStack(){let s=$('stackplot');s.replaceChildren();const bottom=385,scale=3.15;[0,25,50,75,100].forEach(v=>{let yy=bottom-v*scale;el('line',{x1:48,y1:yy,x2:740,y2:yy,stroke:'#e2eaee'},s);label(s,42,yy+4,'$'+v+'B',{'text-anchor':'end'})});DATA.forEach((d,i)=>{let x=60+i*96,g=el('g',{class:'selectable '+(selected===d.year?'active':''),tabindex:0,role:'button'},s),current=bottom;d.parts.forEach((v,j)=>{let h=v*scale;current-=h;let r=el('rect',{x,y:current,width:64,height:h,fill:META[j].color},g);let t=el('title',{},r);t.textContent=META[j].label+': '+fmt(v)});el('rect',{class:'border',x,y:current,width:64,height:bottom-current,fill:'none',stroke:'transparent'},g);label(g,x+32,408,d.year,{'text-anchor':'middle'});g.onclick=()=>pick(d.year);g.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();pick(d.year)}}})}function renderDetails(d){$('detailheading').textContent='FY'+d.year+' composition';let body=$('detail');body.replaceChildren();d.parts.forEach((v,i)=>{let tr=document.createElement('tr');let a=document.createElement('td');a.innerHTML='<i class="dot" style="background:'+META[i].color+'"></i>'+META[i].label;let b=document.createElement('td');b.textContent=fmt(v);tr.append(a,b);body.append(tr)});let tr=document.createElement('tr');tr.innerHTML='<td>Total identified inflows</td><td>'+fmt(d.inflows)+'</td>';body.append(tr)}function renderCovid(){let root=$('covidbars');root.replaceChildren();let max=30;DATA.forEach(d=>{let col=document.createElement('div');col.className='barwrap'+(selected===d.year?' active':'');col.tabIndex=0;col.setAttribute('role','button');let value=document.createElement('div');value.className='value';value.textContent=fmt(d.covid);let total=d.parts[9],base=document.createElement('div');base.style.cssText='width:65%;max-width:68px;height:'+total/max*230+'px;display:flex;flex-direction:column;justify-content:flex-end';let other=document.createElement('div');other.style.cssText='background:#a8b7bf;height:'+Math.max(0,(total-d.covid)/max*230)+'px';let cov=document.createElement('div');cov.style.cssText='background:#cb7554;height:'+d.covid/max*230+'px';base.append(other,cov);let year=document.createElement('small');year.textContent=d.year;col.append(value,base,year);col.onclick=()=>pick(d.year);col.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();pick(d.year)}};root.append(col)});let d=DATA.find(x=>x.year===selected);$('covidtitle').textContent='FY'+selected+' COVID-tagged assistance';$('coviddetail').textContent=fmt(d.covid)+' COVID-tagged within '+fmt(d.parts[9])+' established additive assistance. IIJA-tagged: '+fmt(d.iija)+'; overlap of COVID and IIJA tags: '+fmt(d.both)+'.'}function renderAgency(){let root=$('agencybars');root.replaceChildren();let max=17;DATA.forEach(d=>{let col=document.createElement('div');col.className='barwrap'+(selected===d.year?' active':'');col.tabIndex=0;col.setAttribute('role','button');let v=document.createElement('div');v.className='value';v.textContent=fmt(d.dod+d.doe);let bar=document.createElement('div');bar.style.cssText='width:65%;max-width:68px;height:'+(d.dod+d.doe)/max*230+'px;display:flex;flex-direction:column;justify-content:flex-end';let doe=document.createElement('div');doe.style.cssText='background:#d4a65a;height:'+d.doe/max*230+'px';let dod=document.createElement('div');dod.style.cssText='background:#49759b;height:'+d.dod/max*230+'px';bar.append(doe,dod);let y=document.createElement('small');y.textContent=d.year;col.append(v,bar,y);col.onclick=()=>pick(d.year);col.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();pick(d.year)}};root.append(col)});let d=DATA.find(x=>x.year===selected);$('agencytitle').textContent='FY'+selected+' procurement obligations';$('agencydetail').textContent='DoD: '+fmt(d.dod)+' (blue); DOE: '+fmt(d.doe)+' (gold); combined: '+fmt(d.dod+d.doe)+'. Other non-VA procurement: '+fmt(d.otherproc)+'. These amounts are not added to the Provisional Reference.'}META.forEach(m=>{let x=document.createElement('span');x.innerHTML='<i class="dot" style="background:'+m.color+'"></i>'+m.label;$('legend').append(x)});document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-view]').forEach(z=>z.setAttribute('aria-selected',z===b?'true':'false'));document.querySelectorAll('.view').forEach(v=>v.hidden=v.id!=='view-'+b.dataset.view)});pick(2024);</script></body></html>'''
(ROOT/'index.html').write_text(page.replace('__DATA__',JS).replace('__META__',META),encoding='utf-8')
print('PASS: 7 years x 11 segments, exact cent reconciliation; dashboard and chart data written')
